//! The TLS identity WebTransport needs. Browsers accept a self-signed certificate only through
//! `serverCertificateHashes`, and only an ECDSA P-256 one valid 14 days or less, so a self-signed identity is
//! regenerated by the gateway (at start and every [`ROTATE_AFTER`]) and its hash is given to the page. A
//! certificate the browser trusts on its own (Tailscale's, for instance) is loaded from PEM files instead.

use std::path::{Path, PathBuf};
use std::time::Duration;

use wtransport::Identity;
use wtransport::tls::Sha256DigestFmt;

/// How long a self-signed identity is used before a new one is made: half the 14 day maximum, so there is a week
/// of margin before a certificate a browser would refuse. After a rotation only the new hash connects, which is why
/// pages fetch the hash fresh on every connect and the gateway never hands out a stale copy.
pub const ROTATE_AFTER: Duration = Duration::from_secs(7 * 24 * 3600);

/// Where the identity comes from.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CertSource {
    /// PEM files with a certificate chain and its private key.
    Pem {
        /// The certificate chain.
        cert: PathBuf,
        /// The private key.
        key: PathBuf,
    },
    /// A self-signed certificate for these names, regenerated by the gateway.
    SelfSigned {
        /// Subject alternative names: the host names and addresses the page will connect to.
        names: Vec<String>,
    },
}

/// Why no identity could be made.
#[derive(Debug, thiserror::Error)]
pub enum CertError {
    /// A PEM file couldn't be read or parsed.
    #[error("loading {0}: {1}")]
    Pem(PathBuf, String),
    /// A name isn't a valid subject alternative name.
    #[error("self-signed certificate: {0}")]
    Name(String),
}

/// Makes the identity.
///
/// # Errors
///
/// [`CertError`].
pub async fn identity(source: &CertSource) -> Result<Identity, CertError> {
    match source {
        CertSource::Pem { cert, key } => {
            Identity::load_pemfiles(cert, key).await.map_err(|e| CertError::Pem(cert.clone(), e.to_string()))
        }
        CertSource::SelfSigned { names } => Identity::self_signed_builder()
            .subject_alt_names(names)
            .from_now_utc()
            .validity_days(14)
            .build()
            .map_err(|e| CertError::Name(e.to_string())),
    }
}

/// The SHA-256 of the leaf certificate, lower-case hex: what the page passes in `serverCertificateHashes`.
#[must_use]
pub fn leaf_hash_hex(identity: &Identity) -> String {
    let digest = identity.certificate_chain().as_slice().first().map(wtransport::tls::Certificate::hash);
    digest.map(|d| d.fmt(Sha256DigestFmt::DottedHex).replace(':', "").to_ascii_lowercase()).unwrap_or_default()
}

/// Whether a path pair was given, for the command line.
#[must_use]
pub fn pem_source(cert: Option<&Path>, key: Option<&Path>) -> Option<CertSource> {
    Some(CertSource::Pem { cert: cert?.to_path_buf(), key: key?.to_path_buf() })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn a_self_signed_identity_is_p256_short_lived_and_hashable() {
        let id = identity(&CertSource::SelfSigned { names: vec!["localhost".to_owned(), "127.0.0.1".to_owned()] })
            .await
            .expect("identity");
        let hash = leaf_hash_hex(&id);
        assert_eq!(hash.len(), 64, "{hash}");
        assert!(hash.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
        let der = id.certificate_chain().as_slice()[0].der().to_vec();
        // The DER names the P-256 curve (OID 1.2.840.10045.3.1.7) somewhere in the SubjectPublicKeyInfo.
        let p256 = [0x06, 0x08, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x03, 0x01, 0x07];
        assert!(der.windows(p256.len()).any(|w| w == p256), "not a P-256 certificate");
        let missing = CertSource::Pem { cert: "/nonexistent/c.pem".into(), key: "/nonexistent/k.pem".into() };
        assert!(matches!(identity(&missing).await, Err(CertError::Pem(..))));
        assert_eq!(pem_source(Some(Path::new("c")), None), None);
    }
}
